  <script>
    const FIELD_DEFS = [
      {
        name: 'fullName',
        label: 'Full name',
        type: 'text',
        required: true,
        autocomplete: 'name',
        placeholder: 'Jane Doe',
      },
      {
        name: 'email',
        label: 'Email address',
        type: 'email',
        required: true,
        autocomplete: 'email',
        placeholder: 'jane@company.com',
      },
      {
        name: 'phone',
        label: 'Phone number',
        type: 'tel',
        required: false,
        autocomplete: 'tel',
        placeholder: '(555) 123-4567',
      },
    ];

    function escapeHtml(value) {
      return String(value)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#39;');
    }

    function FormField({ id, label, type, required, autocomplete, placeholder, helpText, errorText = '' }) {
      const requiredMark = required ? '<span class="required-mark" aria-hidden="true">*</span>' : '';
      const describedBy = [helpText ? `${id}-help` : '', `${id}-error`].filter(Boolean).join(' ');
      const requiredAttrs = required ? 'required aria-required="true"' : '';
      const invalidAttr = errorText ? 'aria-invalid="true"' : 'aria-invalid="false"';
      const inputPattern = type === 'email' ? 'pattern="[^\\s@]+@[^\\s@]+\\.[^\\s@]+"' : '';
      return `
        <div class="form-field">
          <label for="${id}">${escapeHtml(label)} ${requiredMark}</label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            ${requiredAttrs}
            ${invalidAttr}
            ${autocomplete ? `autocomplete="${autocomplete}"` : ''}
            ${placeholder ? `placeholder="${escapeHtml(placeholder)}"` : ''}
            ${describedBy ? `aria-describedby="${describedBy}"` : ''}
            ${inputPattern}
          >
          ${helpText ? `<p id="${id}-help" class="field-help">${escapeHtml(helpText)}</p>` : ''}
          <p id="${id}-error" class="field-error" aria-live="polite">${escapeHtml(errorText)}</p>
        </div>
      `;
    }

    function SupportForm({ formId = 'support-form' }) {
      return `
        <section class="support-shell" aria-labelledby="support-heading">
          <aside class="support-intro">
            <div>
              <div class="eyebrow">Support</div>
              <h1 id="support-heading">Contact our support team</h1>
              <p class="intro-copy">Send a message and we will get back to you as soon as possible. Keep it simple, and we will route it to the right person.</p>
            </div>
            <ul class="support-points" aria-label="What happens next">
              <li><span aria-hidden="true">1</span><div>We review every request during business hours.</div></li>
              <li><span aria-hidden="true">2</span><div>Urgent issues are prioritized for a faster response.</div></li>
              <li><span aria-hidden="true">3</span><div>We only use your details to reply about this request.</div></li>
            </ul>
          </aside>

          <section class="support-form-card" aria-labelledby="form-title">
            <div class="form-header">
              <h2 id="form-title">Send a support request</h2>
              <p>Fields marked with an asterisk are required.</p>
            </div>

            <form id="${formId}" novalidate>
              ${FormField({
                id: 'fullName',
                label: 'Full name',
                type: 'text',
                required: true,
                autocomplete: 'name',
                placeholder: 'Jane Doe',
              })}
              ${FormField({
                id: 'email',
                label: 'Email address',
                type: 'email',
                required: true,
                autocomplete: 'email',
                placeholder: 'jane@company.com',
              })}
              ${FormField({
                id: 'phone',
                label: 'Phone number',
                type: 'tel',
                required: false,
                autocomplete: 'tel',
                placeholder: '(555) 123-4567',
                helpText: 'Optional. Use a format like (555) 123-4567 or 555-123-4567.',
              })}

              <div class="form-actions">
                <p class="form-note">We will only use the details you provide to respond to this request.</p>
                <button type="submit">Submit request</button>
              </div>

              <div class="form-status" id="form-status" aria-live="polite">
                Ready when you are.
              </div>
            </form>
          </section>
        </section>
      `;
    }

    function App() {
      return `
        <header class="visually-hidden">
          <p>Support contact page</p>
        </header>
        <main id="main-content" class="page">
          ${SupportForm({ formId: 'support-form' })}
        </main>
        <footer class="visually-hidden">
          <p>Support contact form.</p>
        </footer>
      `;
    }

    function getFieldElements(form) {
      return FIELD_DEFS.reduce((acc, field) => {
        acc[field.name] = form.elements[field.name];
        return acc;
      }, {});
    }

    function validateField(fieldDef, value) {
      const trimmed = value.trim();
      if (fieldDef.required && !trimmed) {
        return `${fieldDef.label} is required.`;
      }
      if (fieldDef.name === 'email' && trimmed) {
        const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
        if (!emailOk) {
          return 'Enter a valid email address.';
        }
      }
      if (fieldDef.name === 'phone' && trimmed) {
        const phoneOk = /^[0-9()+.\-\s]{7,}$/.test(trimmed);
        if (!phoneOk) {
          return 'Enter a valid phone number or leave it blank.';
        }
      }
      return '';
    }

    function setFieldState(form, fieldDef, errorText) {
      const input = form.elements[fieldDef.name];
      const errorEl = document.getElementById(`${fieldDef.name}-error`);
      input.setAttribute('aria-invalid', errorText ? 'true' : 'false');
      errorEl.textContent = errorText;
    }

    function validateForm(form) {
      const fieldElements = getFieldElements(form);
      let firstInvalid = null;
      const errors = [];

      FIELD_DEFS.forEach((fieldDef) => {
        const errorText = validateField(fieldDef, fieldElements[fieldDef.name].value);
        setFieldState(form, fieldDef, errorText);
        if (errorText) {
          errors.push(errorText);
          if (!firstInvalid) {
            firstInvalid = fieldElements[fieldDef.name];
          }
        }
      });

      return { valid: errors.length === 0, firstInvalid, errors };
    }

    function bindFormBehavior() {
      const form = document.getElementById('support-form');
      const status = document.getElementById('form-status');

      FIELD_DEFS.forEach((fieldDef) => {
        const input = form.elements[fieldDef.name];
        const touch = () => {
          const errorText = validateField(fieldDef, input.value);
          setFieldState(form, fieldDef, errorText);
          if (errorText) {
            status.dataset.state = 'error';
            status.textContent = 'Please fix the highlighted fields.';
          } else if (Array.from(form.elements).every((el) => !el.matches || !el.matches('input') || el.getAttribute('aria-invalid') !== 'true')) {
            status.dataset.state = '';
            status.textContent = 'Ready when you are.';
          }
        };
        input.addEventListener('blur', touch);
        input.addEventListener('input', touch);
      });

      form.addEventListener('submit', (event) => {
        event.preventDefault();
        const result = validateForm(form);
        if (!result.valid) {
          status.dataset.state = 'error';
          status.textContent = 'Please fix the highlighted fields.';
          result.firstInvalid.focus();
          return;
        }

        status.dataset.state = 'success';
        status.textContent = 'Your request is ready to send.';
        form.reset();
        FIELD_DEFS.forEach((fieldDef) => setFieldState(form, fieldDef, ''));
        form.elements.fullName.focus();
      });
    }

    document.getElementById('app').innerHTML = App();
    bindFormBehavior();
  </script>
</body>
</html>
