       --border-strong: #9badc4;
       --primary: #2457d6;
       --primary-hover: #1d49b4;
       --primary-text: #ffffff;
       --error: #b42318;
       --error-bg: #fff3f1;
       --success: #157347;
       --shadow: 0 18px 45px #10203314;
       --radius: 20px;
       --focus: #0f62fe;
     }

     * { box-sizing: border-box; }

     html {
       scroll-behavior: smooth;
     }

     body {
       margin: 0;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       line-height: 1.5;
       color: var(--text);
       background:
         radial-gradient(circle at top, #ffffff 0, #f4f7fb 38%, #edf3fb 100%);
     }

     a {
       color: inherit;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       padding: 0.75rem 1rem;
       background: var(--surface);
       border: 2px solid var(--focus);
       border-radius: 999px;
       transform: translateY(-180%);
       transition: transform 0.2s ease;
       z-index: 10;
     }

     .skip-link:focus {
       transform: translateY(0);
       outline: 2px solid transparent;
     }

     .page {
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 1.25rem;
     }

     .support-shell {
       width: min(100%, 980px);
       display: grid;
       gap: 1.25rem;
       grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
       align-items: stretch;
     }

     .support-intro,
     .support-form-card {
       background: var(--surface);
       border: 1px solid var(--border);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
     }

     .support-intro {
       padding: clamp(1.5rem, 3vw, 2.5rem);
       display: flex;
       flex-direction: column;
       justify-content: space-between;
       gap: 1.5rem;
       background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 0.5rem;
       width: fit-content;
       padding: 0.4rem 0.75rem;
       border-radius: 999px;
       background: #eaf1ff;
       color: #2348a6;
       font-size: 0.875rem;
       font-weight: 700;
       letter-spacing: 0.01em;
     }

     h1 {
       margin: 0.6rem 0 0;
       font-size: clamp(2rem, 4vw, 3.25rem);
       line-height: 1.05;
       letter-spacing: -0.03em;
     }

     .intro-copy {
       margin: 1rem 0 0;
       color: var(--muted);
       font-size: 1.05rem;
       max-width: 38ch;
     }

     .support-points {
       display: grid;
       gap: 0.875rem;
       margin: 0;
       padding: 0;
       list-style: none;
       color: var(--text);
     }

     .support-points li {
       display: flex;
       gap: 0.75rem;
       align-items: flex-start;
       min-width: 0;
     }

     .support-points span {
       display: inline-grid;
       place-items: center;
       flex: 0 0 auto;
       width: 1.5rem;
       height: 1.5rem;
       border-radius: 50%;
       background: #e8f7ef;
       color: var(--success);
       font-weight: 800;
       font-size: 0.85rem;
     }

     .support-form-card {
       padding: clamp(1.25rem, 2.5vw, 2rem);
     }

     .form-header {
       margin-bottom: 1.25rem;
     }

     .form-header h2 {
       margin: 0;
       font-size: 1.4rem;
       line-height: 1.2;
     }

     .form-header p {
       margin: 0.45rem 0 0;
       color: var(--muted);
     }

     form {
       display: grid;
       gap: 1rem;
     }

     .form-field {
       display: grid;
       gap: 0.45rem;
     }

     label {
       font-weight: 700;
       color: var(--text);
     }

     .required-mark {
       color: var(--error);
     }

     input {
       width: 100%;
       min-width: 0;
       padding: 0.95rem 1rem;
       border: 1px solid var(--border);
       border-radius: 14px;
       background: var(--surface-alt);
       color: var(--text);
       font: inherit;
       transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
     }

     input::placeholder {
       color: #7a889d;
     }

     input:hover {
       border-color: var(--border-strong);
       background: #ffffff;
     }

     input:focus {
       outline: 3px solid transparent;
       border-color: var(--focus);
       box-shadow: 0 0 0 4px #dce8ff;
       background: #ffffff;
     }

     input[aria-invalid="true"] {
       border-color: var(--error);
       box-shadow: 0 0 0 4px #fbe4e0;
     }

     .field-help {
       margin: 0;
       color: var(--muted);
       font-size: 0.95rem;
     }

     .field-error {
       margin: 0;
       color: var(--error);
       font-size: 0.95rem;
       font-weight: 600;
       min-height: 1.4em;
     }

     .form-actions {
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 1rem;
       margin-top: 0.25rem;
       flex-wrap: wrap;
     }

     .form-note {
       margin: 0;
       color: var(--muted);
       font-size: 0.95rem;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       background: var(--primary);
       color: var(--primary-text);
       font: inherit;
